  const n = nums1.length;

  function countSwaps(last1, last2) {
    let swaps = 0;
    for (let i = 0; i < n - 1; i++) {
      if (nums1[i] <= last1 && nums2[i] <= last2) {
        continue;
      }
      if (nums2[i] <= last1 && nums1[i] <= last2) {
        swaps++;
      } else {
        return Infinity;
      }
    }
    return swaps;
  }

  const keepLast = countSwaps(nums1[n - 1], nums2[n - 1]);
  const swapLast = 1 + countSwaps(nums2[n - 1], nums1[n - 1]);
  const best = Math.min(keepLast, swapLast);
  return best === Infinity ? -1 : best;
}

