function minOperations(nums1, nums2) {
  // Try every subset of positions to swap and keep the smallest one that works.
  const n = nums1.length;
  let best = -1;
  for (let mask = 0; mask < (1 << n); mask++) {
    const a = [], b = [];
    let ops = 0;
    for (let i = 0; i < n; i++) {
      if (mask & (1 << i)) { a.push(nums2[i]); b.push(nums1[i]); ops++; }
      else { a.push(nums1[i]); b.push(nums2[i]); }
    }
    if (a[n - 1] === Math.max(...a) && b[n - 1] === Math.max(...b)) {
      if (best === -1 || ops < best) best = ops;
    }
  }
  return best;
}

