function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? 1000 : int(1, 7);
  const cap = size === 'large' ? 1000000000 : int(2, 8);
  if (rand() < 0.25) {
    return [Array.from({ length: n }, () => int(1, cap)), Array.from({ length: n }, () => int(1, cap))];
  }
  // Build a solvable layout, then scramble it with random swaps.
  const top1 = int(1, cap);
  const top2 = int(1, cap);
  const nums1 = [];
  const nums2 = [];
  for (let i = 0; i < n - 1; i++) {
    nums1.push(int(1, top1));
    nums2.push(int(1, top2));
  }
  nums1.push(top1);
  nums2.push(top2);
  const chance = rand();
  for (let i = 0; i < n; i++) {
    if (rand() < chance) [nums1[i], nums2[i]] = [nums2[i], nums1[i]];
  }
  if (n > 1 && rand() < 0.2) {
    const k = int(0, n - 2);
    nums1[k] = int(1, cap);
  }
  return [nums1, nums2];
}
